1	/* ==========================================================
2	   works-sec  (Webflow: .works-sec)
3	   ========================================================== */
4	.worksSec {
5	  background-color: transparent;
6	  padding: 20px 5% 60px;
7	  position: relative;
8	}
9	
10	/* ==========================================================
11	   Container  (Webflow: .container-large-3)
12	   ========================================================== */
13	.containerLarge3 {
14	  width: 100%;
15	  max-width: 1280px;
16	  margin-left: auto;
17	  margin-right: auto;
18	}
19	
20	/* ==========================================================
21	   Badge row  (Webflow: .benefit-subhead-out / .benefitsubott)
22	   ========================================================== */
23	.benefitSubheadOut {
24	  grid-column-gap: 10px;
25	  grid-row-gap: 10px;
26	  justify-content: center;
27	  align-items: center;
28	  display: flex;
29	}
30	
31	.benefitsubott {
32	  background-color: #21cfff12;
33	  border: 1px solid #05bafe;
34	  border-radius: 20px;
35	  margin-bottom: 0;
36	  padding: 0 13px;
37	  line-height: 14px;
38	}
39	
40	/* ==========================================================
41	   Gradient text  (Webflow: .faq-sky-text)
42	   ========================================================== */
43	.faqSkyText {
44	  color: #21cfff;
45	  text-transform: capitalize;
46	  -webkit-text-fill-color: transparent;
47	  background-image: linear-gradient(90deg, #21cfff, #019ae6);
48	  -webkit-background-clip: text;
49	  background-clip: text;
50	  font-weight: 500;
51	}
52	
53	/* ==========================================================
54	   Section heading  (Webflow: .heading-2.margin-bottom-24px)
55	   ========================================================== */
56	.heading2 {
57	  color: #082753;
58	  font-family: Roobert PRO, Arial, sans-serif;
59	  font-size: 40px;
60	  text-align: center;
61	  line-height: 45px;
62	  margin-bottom: 20px;
63	}
64	
65	/* ==========================================================
66	   Body copy  (Webflow: .paragraph.center)
67	   ========================================================== */
68	.paragraph {
69	  color: #2b2b2b;
70	  font-size: 16px;
71	  line-height: 28px;
72	  text-align: center;
73	  margin-bottom: 0;
74	}
75	
76	/* ==========================================================
77	   Grid  (Webflow: .feature-grid.margin-top-40px.hiring-slider)
78	   Desktop: 3-col grid with scroll snapping disabled — Slick
79	   converts it to carousel only at < 980px in Webflow. We
80	   replicate with CSS scroll-snap at ≤767px.
81	   ========================================================== */
82	.featureGrid {
83	  display: grid;
84	  grid-column-gap: 20px;
85	  grid-row-gap: 20px;
86	  grid-template-rows: auto;
87	  grid-template-columns: 1fr 1fr 1fr;
88	  margin-top: 40px;
89	}
90	
91	/* ==========================================================
92	   Card  (Webflow: .feature-card.space-between)
93	   Note: .space-between modifier sets justify-content: space-between
94	   ========================================================== */
95	.featureCard {
96	  grid-column-gap: 0px;
97	  grid-row-gap: 0px;
98	  text-align: center;
99	  mix-blend-mode: normal;
100	  background-color: #def4ff;
101	  background-image: none;
102	  border: 1px solid #009ce0;
103	  border-radius: 20px;
104	  flex-flow: column;
105	  justify-content: space-between;
106	  align-items: center;
107	  padding: 25px 17px 17px;
108	  text-decoration: none;
109	  display: flex;
110	}
111	
112	.featureCard:hover {
113	  background-color: #cdebfa;
114	  border-color: #009ce0;
115	}
116	
117	/* ==========================================================
118	   Text wrapper  (Webflow: .text-wrapper)
119	   ========================================================== */
120	.textWrapper {
121	  margin-bottom: 20px;
122	}
123	
124	/* ==========================================================
125	   Card title  (Webflow: .subheading-large)
126	   ========================================================== */
127	.subheadingLarge {
128	  color: #082753;
129	  letter-spacing: -0.02em;
130	  margin-bottom: 10px;
131	  font-family: Roobert PRO, Arial, sans-serif;
132	  font-size: 20px;
133	  font-weight: 700;
134	  line-height: 25px;
135	}
136	
137	/* ==========================================================
138	   Card body copy  (Webflow: .paragraph-small-2.margin-bottom-20px.grid-wrap)
139	   ========================================================== */
140	.paragraphSmall2 {
141	  color: #2b2b2b;
142	  min-height: auto;
143	  font-family: Roobert PRO, Arial, sans-serif;
144	  font-size: 16px;
145	  letter-spacing: -0.08px;
146	  margin-bottom: 0;
147	  line-height: 28px;
148	  max-width: 315px;
149	}
150	
151	/* ==========================================================
152	   Card image  (Webflow: .full-width-image.drop-shadow.blue-shadow)
153	   ========================================================== */
154	.fullWidthImage {
155	  display: block;
156	  width: 100%;
157	  height: auto;
158	  filter: drop-shadow(0px 0px 30px rgba(0, 126, 188, 0.1));
159	}
160	
161	/* ==========================================================
162	   Dots (CSS scroll indicator — replaces Slick dots at mobile)
163	   ========================================================== */
164	.sliderDots {
165	  display: none;
166	}
167	
168	/* ==========================================================
169	   @media (min-width: 1280px)
170	   Webflow line 21922 — .feature-card, .container-large-3
171	   ========================================================== */
172	@media screen and (min-width: 1280px) {
173	  .featureCard {
174	    background-color: #def4ff;
175	    border-color: #009ce0;
176	  }
177	
178	  .containerLarge3 {
179	    max-width: 1280px;
180	  }
181	
182	  .paragraphSmall2 {
183	    max-width: 308px;
184	  }
185	}
186	
187	/* ==========================================================
188	   @media (min-width: 1440px)
189	   Webflow line 23357 — .feature-card.space-between gets pl/pr 25px
190	   container-large-3 gets max-width: 1320px
191	   ========================================================== */
192	@media screen and (min-width: 1440px) {
193	  .featureCard {
194	    background-color: #def4ff;
195	    background-image: none;
196	    border-color: #009ce0;
197	    justify-content: space-between;
198	    align-items: center;
199	    padding-left: 25px;
200	    padding-right: 25px;
201	  }
202	
203	  .containerLarge3 {
204	    max-width: 1320px;
205	  }
206	
207	  .paragraphSmall2 {
208	    max-width: 308px;
209	    margin-left: auto;
210	    margin-right: auto;
211	  }
212	}
213	
214	/* ==========================================================
215	   @media (max-width: 991px)
216	   Webflow line 24558: feature-grid → 1 col (but margin-top-40px → 3 col)
217	   So .hiring-slider (which also has margin-top-40px) stays 3-col at tablet
218	   ========================================================== */
219	@media screen and (max-width: 991px) {
220	  .featureGrid {
221	    /* hiring-slider keeps 3-col at tablet per Webflow line 24562 */
222	    grid-template-columns: 1fr 1fr 1fr;
223	    grid-column-gap: 20px;
224	    grid-row-gap: 20px;
225	  }
226	
227	  .paragraphSmall2 {
228	    max-width: none;
229	  }
230	
231	  .heading2 {
232	    font-size: 35px;
233	    line-height: 45px;
234	  }
235	}
236	
237	/* ==========================================================
238	   @media (max-width: 767px)
239	   Webflow line 27051: .feature-grid.margin-top-40px → 1 col
240	   Webflow line 27055: .feature-grid.margin-top-40px.hiring-slider → 20px gap (Slick takes over)
241	   Webflow line 27177: .works-sec → padding-top: 0; padding-bottom: 50px
242	   We implement hiring-slider as CSS horizontal scroll carousel
243	   ========================================================== */
244	@media screen and (max-width: 767px) {
245	  .worksSec {
246	    padding-top: 0;
247	    padding-bottom: 50px;
248	  }
249	
250	  /* Horizontal scroll carousel mimicking Slick slidesToShow:2 at tablet */
251	  .featureGrid {
252	    grid-template-columns: unset;
253	    grid-template-rows: unset;
254	    display: flex;
255	    flex-direction: row;
256	    overflow-x: auto;
257	    scroll-snap-type: x mandatory;
258	    -webkit-overflow-scrolling: touch;
259	    scroll-padding-left: 5%;
260	    gap: 20px;
261	    margin-top: 20px;
262	    /* hide scrollbar */
263	    scrollbar-width: none;
264	  }
265	
266	  .featureGrid::-webkit-scrollbar {
267	    display: none;
268	  }
269	
270	  .featureCard {
271	    flex: 0 0 calc(50% - 10px);
272	    min-width: calc(50% - 10px);
273	    scroll-snap-align: start;
274	    grid-column-gap: 0px;
275	    grid-row-gap: 0px;
276	    padding-left: 18px;
277	    padding-right: 18px;
278	  }
279	
280	  .paragraphSmall2 {
281	    text-align: center;
282	    max-width: none;
283	  }
284	
285	  .subheadingLarge {
286	    text-align: center;
287	  }
288	
289	  .heading2 {
290	    font-size: 23px;
291	    line-height: 28px;
292	    margin-bottom: 10px;
293	    text-align: center;
294	  }
295	
296	  .textWrapper {
297	    text-align: center;
298	  }
299	}
300	
301	/* ==========================================================
302	   @media (max-width: 479px)
303	   Webflow line 29597: .feature-grid.margin-top-40px.hiring-slider → margin-top: 20px, 20px gap
304	   Webflow line 29826: .works-sec → padding-top: 0; padding-bottom: 35px
305	   Slick shows 1 slide — we show 1 card at a time
306	   ========================================================== */
307	@media screen and (max-width: 479px) {
308	  .worksSec {
309	    padding-top: 0;
310	    padding-bottom: 35px;
311	  }
312	
313	  .featureGrid {
314	    margin-top: 20px;
315	    gap: 20px;
316	  }
317	
318	  .featureCard {
319	    flex: 0 0 calc(100% - 0px);
320	    min-width: calc(100%);
321	    padding: 24px 18px;
322	  }
323	
324	  .paragraphSmall2 {
325	    text-align: center;
326	    max-width: none;
327	  }
328	
329	  .subheadingLarge {
330	    text-align: center;
331	  }
332	}
